function numRollsToTarget(n, k, target) {
  // Inclusion-exclusion with exact BigInt arithmetic: values y_i = x_i - 1 in [0, k - 1] sum to target - n.
  const choose = (a, b) => {
    if (b < 0 || a < b) return 0n;
    let result = 1n;
    for (let i = 1; i <= b; i++) result = result * BigInt(a - b + i) / BigInt(i);
    return result;
  };
  const rest = target - n;
  if (rest < 0) return 0;
  let total = 0n;
  for (let j = 0; j <= n && j * k <= rest; j++) {
    const term = choose(n, j) * choose(rest - j * k + n - 1, n - 1);
    total += j % 2 === 0 ? term : -term;
  }
  return Number(total % 1000000007n);
}

