function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(20, 30), k = int(15, 30);
    const middle = Math.round(n * (k + 1) / 2);
    const target = Math.max(1, Math.min(1000, middle + int(-80, 80)));
    return [n, k, target];
  }
  const n = int(1, 5), k = int(1, 6);
  return [n, k, int(1, n * k + 3)];
}
